<template lang="pug">
  .slide(:style="slideStyle()")
    .slide__item(
      :style="slideItemStyle()"
    )
      .slide__content(
        v-show="slideItemContentShow"
      )
        .slide__title {{slideItemContentName}}
        .slide__compatibility Full compatibility
        .slide__button
          a(:class="{disabled: disableButton}" :href="slideItemContentHref" onclick="return true;") to Steam
    .slide__content__adaptiv 
      span.slide__text_bold {{slideItemContentTitleBold}}
      span.slide__text_normal {{slideItemContentTitleNormal}}
</template>

<script>

export default {
  name: "hooper-slide-item",
  components: {
   
  },
  props: {
    slideItemContentName: {
      type: String,
      required: false,
      default: ''
    },
    slideItemHeight: {
      type: Number,
      required:false,
      default: 100
    },
    slideItemContentHref: {
      type: String,
      required:false,
      default: ''
    },
    slideItemImage: {
      type: String,
      required:false,
      default: ''
    },
    slideItemContentShow: {
      type: Boolean,
      required: false,
      default: true
    },
    disableButton: {
      type: Boolean,
      required: false
    },
    slideItemContentTitleBold: {
      type: String,
      required: false,
      default: ''
    },
    slideItemContentTitleNormal: {
      type: String,
      required: false,
      default: ''
    },
  },
  data: () => ({
   
  }),
  methods: {
    slideItemStyle: function () {
      return {
        //backgroundImage: `url(${this.slideItemImage})`
        backgroundImage: `url(${require(`@/assets/images/integration/${this.slideItemImage}`)})`
        
      }
    },
    slideStyle: function () {
      if (this.slideItemHeight == 50) {
        return {height: 'calc(50% - 2.5px)', }
      } else {
         return {height: this.slideItemHeight + '%'}
      }
      
    }
  },
}

</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.slide {
  position: relative;
  overflow: hidden;
  margin: 5px 2.5px 0px 2.5px;
  border: 1px solid grayColor(100);
 
  .slide__item {
    height: 100%;
    width: 100%;
    padding-bottom: 100px;
    background-repeat: no-repeat;
    background-position: 50% 50%;
    background-size: cover;

    &:hover {
      transform: scale(1.03); 
      transition: all 0.3s ease;

      .slide__content{
        display: block;
      }
    }
    
    .slide__content {
      display: none;
      position: absolute;
      text-align: left;
      top: 102px;
      left: 27px;
      
      .slide__title {
        @include baseText(Bold, 36px);
        text-transform: uppercase;
      }
      
      .slide__compatibility {
        @include baseText(Thin);
        position: relative;

        &::before {
          content: '';
          position: absolute;
          top: 50%;
          left: 154px;
          height: 1px;
          width: 207px;
          background-color: $mainTextColor;
        }
      }

      .slide__button {
        width: 204px;
        height: 42px;
        background: mainButtonColor();
        opacity: 0.7;
        border-radius: 5px;

        &:hover {
          background: mainButtonColor(hover);
        }

        &:active {
          background: mainButtonColor(active);
        }

        a {
          display: block;
          text-decoration: none;
          color: $mainTextColor;
          text-align: center;
          height: 100%;
          line-height: 42px;
          margin-top: 13px;
        }
      }
    }
  }
}

.disabled {
  cursor: not-allowed;
}
@media (max-width:768px){
  .slide{
    border: none;

    .slide__item{
      height: 360px;
    }

    &__content__adaptiv{
      width: 100%;
      text-align: left;
      position: relative;
      padding: 10px 0;

      &::before{
        content: '';
        position: absolute;
        top: 50%;
        left: 35%;
        height: 1px;
        width: 60%;
        background-color: #fff;
      }

      .slide__text_bold{
        @include baseText(Regular, 18px);
        text-transform: uppercase;
        margin-left: 5%;
        font-weight: 900;
      }

      .slide__text_normal{
        @include baseText(Regular, 18px);
        text-transform: uppercase;
        font-weight: 100;
      }
    }
  }
}

@media (max-width:425px) {
  .slide {
      
    .slide__item {
      height: 340px;

      &:hover {
        
      }
      
      .slide__content {
        top: 20px;
        left: 20px;
        
        .slide__title {
          font-size: 18px;
        }
        
        .slide__compatibility {
          font-size: 14px;

          &::before {
            left: 120px;
            width: 100px;
          }
        }

        .slide__button {
          width: 120px;
          height: 30px;
         
          a {
            font-size: 14px;
            line-height: 30px;
            margin-top: 30px;
          }
        }
      }
    }
    &__content__adaptiv {
      width: 100%;
      text-align: left;
      position: relative;
      padding: 10px 0;

      &::before{
        content: '';
        position: absolute;
        top: 50%;
        left: 62%;
        height: 1px;
        width: 30%;
        background-color: #fff;
      }
      .slide__text_bold{
        @include baseText(Regular, 16px);
      }

      .slide__text_normal{
        @include baseText(Regular, 16px);
      }
    }
  }
}

</style>