<template lang="pug">
  .base_textarea_wrapper
    textarea.base_textarea(
      :name="name"
      :placeholder="placeholder"
      :style="inputStyle"
      :rows="rows"
      :disabled="disabled"
      v-model="content"
      @blur.prevent="blurHandler"
      @keydown.enter.exact.prevent
      @keyup.enter.exact.prevent="keyUpHandler"
      @keydown.enter.shift.exact
      )
</template>

<script>

export default {
  name: "base_textarea",
  components: {
    
  },
  props: {
    format: {
      type: Function,
      required: false,
      default: (val) => val,
    },
    value: {
      type: String,
      required: false,
      default: "",
    },
    name: {
      type: String,
      required: false,
      default: "textarea",
    },
    rows: {
      type: String,
      required: false,
      default: "4",
    },
    placeholder: {
      type: String,
      required: false,
      default: "",
    },
    inputStyle: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    valid: {
      type: Boolean,
      required: false,
      default: false,
    },
    disabled: {
      type: Boolean,
      required: false,
      default: false,
    },
  },
  data: () => ({
    content: "",
  }),
  created() {
    this.content = this.value
  },
  computed: {
    
  },
  watch: {
    content: {
      handler(val) {
        console.log(val)
        let $formatedContent = this.format(val)
        this.content = $formatedContent
        this.$emit("input", $formatedContent)
      },
    },
    value: {
      handler(val) {
        this.content = val
      },
    },
  },
  methods: {
    blurHandler: function ($event) {
      if (this.loading) return
      this.$emit("blur", $event)
    },
    keyUpHandler: function ($event) {
      if (this.loading) return
      this.$emit("blur", $event)
    },
  },
}
</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.base_textarea_wrapper {
  position: relative;
  width: 100%;

  .base_textarea {
    @include baseText(Regular, 24px, initial);
    position: relative;
    width: 100%;
    height: 166px;
    padding: 0 18px;
    margin-top: 22px;
    background: $backgroundInput;
    border-radius: 5px;
    border: 1px solid grayColor(100);
    box-sizing: border-box;
    transition: 0.1s;
    resize: none;
    outline: none;
    padding-top: 18px;

    &::placeholder {
      color: $placeholderInput;
    }

    &:hover {
      border-color: grayColor(300);
    }

    &:focus {
      border-color: grayColor(500);
    }

    &:disabled {
      background-color: grayColor(100);
      cursor: not-allowed;
    }
  }
}

@media (max-width: 992px){
  .base_textarea_wrapper{
    
    .base_textarea{
      @include baseText(Regular, 22px, initial);
    }
  }
}

@media (max-width: 768px){
  .base_textarea_wrapper{
    
    .base_textarea{
      @include baseText(Regular, 20px, initial);
      height: 156px;
    }
  }
}

@media (max-width: 425px){
  .base_textarea_wrapper{
    
    .base_textarea{
       @include baseText(Regular, 18px, initial);
      height: 136px;
    }
  }
}
</style>
