<template lang="pug">
  header.header
    .header__video
      video.video(autoplay="autoplay" preload="auto" loop)
        source(src="~@/video/gun_test_2.mp4" type="video/mp4")
        //source(src="~@/video/gun_test_2.webm" type="video/webm")
        //source(src="~@/video/gun_test_2.ogv" type="video/ogv")
    .header__overlay 
      .header__wrapper
        menu-lists(
          :headerMenuLists="headerMenuLists"
          )
        .header__title.title
          .title__name
            .title__name_icon-top
            .title__name_icon-bottom
          .title__number
            .title__number_three
            .title__number_zero
            .title__number_zero
            .title__number_zero
          .title__text vr gaming rifle
        .header__buttons
          main-button(
            :tag="'purchase'"
            @onClick="onClick('purchase')"
            )
        .header__subtitle
          p virtual reality/real sensation

</template>

<script>
import MenuLists from '@/components/MenuLists';
import MainButton from '@/components/MainButton';

export default {
  name: "header-section",
  components: {
    MenuLists,
    MainButton
  },
  data() {
    return {
      headerMenuLists: [
        {id: 1, title: 'gallery'},
        {id: 2, title: 'specification'},
        {id: 3, title: 'integration'},
        {id: 5, title: 'contact us'}
      ],
    };
  },
  methods: {
    onClick: function (purchase) {
      this.$emit("onClick", purchase)
    }
  }
}
</script>
<style lang="scss" >
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.header {
  //position: relative;
  width: 100%;
  height: 817px;
  margin: 0 auto;
  //z-index: 0;

  .header__video{
    z-index: 1;
    position: absolute;
    width: 100%;
    overflow: hidden;
    height: 817px;

    .video{
      position: absolute;
      z-index: 1;
      left: -20%;
      bottom: 0;
      width: 140%;
      height: 1000px;
    }

  }

  &__overlay {
    position: relative;
    width: 100%;
    height: 100%;

    &::after {
      content: '';
      position: absolute;
      top: 0;
      right: 0;
      left: 0;
      bottom: 0;
      background: $overlayHeader;
      z-index: 1;
    }
  }

  &__wrapper {
    @include wrapper($zindex: 3);

    
  }

  &__title {
    position: relative;
    padding-top: 223px;
    z-index: 2;
  }

  .title {
    @include baseColumn();
   
    &__name {

      &_icon-top {
        @include headerTitleImage(434px, 26px, "~@/assets/images/header/zeus-top.svg");
      }

      &_icon-bottom {
        @include headerTitleImage(434px, 26px, "~@/assets/images/header/zeus-bottom.svg");
      }
    }

    &__number {
      @include baseRow();
      padding-top: 28px;

      &_three {
        @include headerTitleImage(50px, 43px, "~@/assets/images/header/num-three.svg");
        margin-right: 8px;
      }

      &_zero {
        @include headerTitleImage(55px, 43px, "~@/assets/images/header/num-zero.svg");
        margin-right: 8px;
      }
    }

    &__text {
      font-size: 24px;
      padding-top: 30px;
      text-transform: uppercase;
      text-shadow: 0px 0px 60px rgba(0, 0, 0, 0.8);
    }
  }

  &__buttons {
    @include baseRow();
    padding-top: 171px;
  }

  &__subtitle {
    @include baseText(Bold, 36px);
    position: relative;
    padding-top: 25px;
    text-transform: uppercase;
    letter-spacing: 0.47em;
    z-index: 3;
  
    p {
      position: relative;
      right: -10px;
      margin: 0;
    }
  }
}
@media (min-width:2140px) {
  .header {
    height: 1150px;

    .header__video{
      height: 1150px;

      .video{
        width: 140%;
        height: 1450px;
        bottom: -15%;
      }
    }
  }
}

@media (min-width:1970px) and (max-width:2140px){
  .header {
    height: 900px;

    .header__video{
      height: 900px;

      .video{
        width: 140%;
        height: 1180px;
        bottom: -19%;
      }
    }
  }
}

@media (min-width:1790px) and (max-width:1970px) {
  .header {

    .header__video{

      .video{
        height: 1100px;
      }
    }
  }
}

@media (max-width:1300px) {
  .header {

    .header__video{

      .video{
        position: absolute;
        z-index: 1;
        left: -20%;
        bottom: -5%;
        width: 140%;
        height: 1000px;
      }
    }
  }
}

@media (max-width:1200px) {
  
  .header {
   background: url("~@/assets/images/header/header-gun.jpg") center center / cover no-repeat;

   .header__video{
      display: none;
    }

    &__wrapper {
      max-width: 950px;
    }

    &__subtitle {
     font-size: 30px;
    }
  }
}

@media (max-width:992px) {
  
  .header {
    background-position-x: left;
    background-position-y: top;

    &__wrapper {
      max-width: 750px;
    }

    &__subtitle {
      font-size: 22px;
    }
  }
}

@media (max-width:768px) {
  
  .header {
    &__menu {
      width: 95%;
      margin: auto;
    }
  }
}

@media (max-width:425px) {
  
  .header {
    height: 568px;
    background-position-x: left;
    background-position-y: top;

    // &__menu {
    //   width: 100%;
    //   margin: 0;
    // }

    // &__overlay {
    //   z-index: 3;
    // }

    // &__wrapper {
    //   max-width: 290px;
    // }

    &__title {
      padding-top: 50px;
    }

    .title {
       
      &__name {

        &_icon-top {
          width: 202px;
          height: 13px;
        }

        &_icon-bottom {
          width: 202px;
          height: 13px;
        }
      }

      &__number {
        padding-top: 12px;

        &_three {
          width: 25px;
          height: 21.5px;
        }

        &_zero {
          width: 28px;
          height: 21.5px;
        }
      }

      &__text {
        font-size: 14px;
        padding-top: 15px;
        
      }
    }

    &__subtitle {
      display: none;
    }

    &__buttons {
      padding-top: 300px;
    }
  }
}

/*      <video loop="loop" preload="preload">
        <source src="~@/video/gun_test_2.mp4" />
      </video>*/
</style>