<template lang="pug">
    section.gallery#gallery(
      :class="{active: checkShowSlider, notactive: checkShowSlider==false}"
      )
      .gallery__wrapper
        .gallery__description.description
          .description__title-with-line.title-with-line
            .title-with-line__text Gallery
            .title-with-line__line

          .description__slider
            .contents
              .contents__block
                .contents__img.contents__img_first
                .contents__text
                  span ZEUS 3000 
                  |is a rifle aimed to level up VR gaming experience and immersion. With the rifle games become even more 
                  span realistic and breathtaking.
                .contents__swipe
                  .swipe.swipe_right
                    .swipe__block.swipe__block_right swipe
              .contents__block
                .contents__img.contents__img_next
                .contents__text 
                  |Creating the rifle with recoil we aspired to re-create the 
                  span real gun shooting experience.
                .contents__swipe
                  .swipe 
                    .swipe__block swipe
              .contents__block
                .contents__img.contents__img_last
                .contents__text 
                  |Excellent ergonomic design and the modes of recoil intensity perfectly suit for 
                  span both rookies 
                  |in VR games and old 
                  span professional gamers.
                .contents__swipe
                  .swipe.swipe_left
                    .swipe__block.swipe__block_left swipe
                    
            
            //- .swipe
            //-   .swipe__block
            //-     .pointer.swipe__left
            //-       .pointer__text SWIPE
            //-       .pointer__arrow.right
            //-   .swipe__block
            //-     .pointer.swipe__centre
            //-       .pointer__arrow.left
            //-       .pointer__text SWIPE
            //-       .pointer__arrow.right
            //-   .swipe__block
            //-     .pointer.swipe__right
            //-       .pointer__arrow.left
            //-       .pointer__text SWIPE

          .description__img
          .description__text_bold ZEUS 3000 is a rifle aimed to level up VR gaming experience and immersion. With the rifle games become even more realistic and breathtaking. 
          .description__text_normal Creating the rifle with recoil we aspired to re-create the real gun shooting experience. Excellent ergonomic design and the modes of recoil intensity perfectly suit for both rookies in VR games and old professional gamers.
          .description__button
            main-button(
            :tag="'purchase'"
            @onClick="onClick('purchase')"
            )
        .gallery__slider
          custom-slider(
          @clickSlider="clickSlider"
          :sliderImages="sliderImages"
          )
</template>

<script>
import MainButton from '@/components/MainButton';
import CustomSlider from '@/components/CustomSlider';

export default {
  name: "gallery-section",
  components: {
    MainButton,
    CustomSlider
  },
  data: () => ({
    
    sliderImages: [
      {id: 1, name: 'gallery-gun-1.jpg'},
      {id: 2, name: 'gallery-gun-2.jpg'},
      {id: 3, name: 'gallery-gun-3.jpg'},
      {id: 4, name: 'gallery-gun-4.jpg'},
      {id: 5, name: 'gallery-gun-5.jpg'},
    ],
    checkShowSlider: null,
    
  }),
  methods: {
    clickSlider(checkShowSlider) {
      if (checkShowSlider) return this.checkShowSlider = true 
      this.checkShowSlider = false
    },
    onClick: function (purchase) {
      this.$emit("onClick", purchase)
    }
  }
}

</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.gallery {
  width: 100%;
  background-color: $mainBackgroundColor;
  padding-top: 96px;
  padding-bottom: 96px;
  overflow: hidden;
  position: relative;
  
  &.active {
    
    .gallery__slider {
      animation: moveSlider 2s ease-in-out;
      right: 0%;
    }

    .title-with-line {

      &__text {
        animation: moveColor 3s ease-in-out;
        position: relative;
        color: black;
        z-index: 1;
        opacity: 1;
      }
    }
  }

  &.notactive {
    .gallery__slider {
      animation: moveSliderBack 2s ease-in-out;
    }
  }

  &__wrapper {
    @include wrapper(static);
  }

  .description {
    text-shadow: 0px 4px 10px rgba(0, 0, 0, 0.7);
    padding-top: 49px;
    max-width: 62%;
    text-align: left;

    &__text {

      &_bold {
        @include baseText(Bold, 36px);
        line-height: 50px;
        padding-top: 25px;
      }

      &_normal {
        @include baseText(Regular, 24px);
        line-height: 40px;
        padding-top: 25px;
      }
    }

    &__button {
      padding-top: 30px;
    }
    &__slider{
      display: none;
    }
  }

  &__slider {
    position: absolute;
    width: 1180px;
    height: 664px;
    margin: 0 auto;
    right: -120%;
    top: 96px;
    left: 0px;
  }

  @keyframes moveSlider {
    0% {
      right: -120%;
    }
    100% {
      right: 0%;
    }
  }
  
  @keyframes moveSliderBack {
    0% {
      right: 0px;
    }
    100% {
      right: -120%;
    }
  }
  
  @keyframes moveColor {
    0% {
      opacity: 1;
      color: white;
    }
    50% {
      opacity: 0;
    }
    100% {
      opacity: 1;
      color: black;
    }
  }
}

