<template lang="pug">
  .main-button(
    :class="theme"
    @click="clickHandler"
    ) 
    .main-button__content(
      ) {{tag}}
</template>

<script>

export default {
  name: "main-button",
  components: {
  },
  props: {
    tag: {
      type: String,
      required: false,
      default: "button",
    },
    theme: {
      type: String,
      required: false,
      default: "purple"
    },
  },
  methods: {
    clickHandler: function () {
      this.$emit("onClick")
      //console.log("click")
    },
  },
}
</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.main-button {
  @include baseText(Bold, 24px);
  position: relative;
  width: 509px;
  height: 67px;
  border-radius: 5px;
  user-select: none;
  cursor: pointer;
  text-transform: uppercase;
  opacity: 0.9;
 
  &:disabled {
    cursor: not-allowed;
  }

  &.gray {
    background: mainButtonColor();
    
    &:hover {
      background: mainButtonColor(hover);
      opacity: 1;
    }

    &:active {
      background: mainButtonColor(active);
    }
  }

  &.purple {
    background: secondButtonColor();
        
    &:hover {
      background: secondButtonColor(hover);
      opacity: 1;
    }

    &:active {
      background: secondButtonColor(active);
    }
  }

  &__content {
    width: 100%;
    height: 100%;
    @include baseRow();
  }
}

@media (max-width:768px) {
  .main-button {
    margin: auto;
    width: 400px;
    height: 69px;
    font-size: 22px;
  }
}

@media (max-width:425px) {
  .main-button {
    width: 273px;
    height: 49px;
    font-size: 18px;
  }
}

</style>
