<template lang="pug">
 .slider(
  :class="{active: checkShowSlider}"
  )
  .slider__wrapper
    .slider__box(:style="sliderBoxStyle()").box
      hooper 
        slide.box__item(
        v-for="sliderImage of sliderImages"
        :key="sliderImage.id"
        :id="sliderImage.id"
        :style="sliderImageStyle(sliderImage.name)"
        )
        hooper-pagination(slot="hooper-addons")
  .slider__arrow.left(@click="clickSlider('left')")
    .arrow
      .arrow__part-up
      .arrow__part-down
  .slider__arrow.right(@click="clickSlider('right')")
    .arrow
      .arrow__part-up
      .arrow__part-down   
</template>

<script>
import { Hooper, Slide, Pagination as HooperPagination } from 'hooper';
import 'hooper/dist/hooper.css';

export default {
  name: "castom-slider",
  components: {
    Hooper,
    Slide,
    HooperPagination
  },
  props: {
    sliderImages: {
      type: Array,
      required: false
    },
  },

  data: () => ({
    checkShowSlider: false,
  }),
  methods: {
    sliderImageStyle: function (name) {
      return {
        //backgroundImage: `url(${path})`,
        backgroundImage: `url(${require(`@/assets/images/gallery/${name}`)})`
      }
    },
    sliderBoxStyle: function () {
      return {
        //width: this.sliderImages.length + '00%',
        //left: '0%'
      }
    },
    clickSlider($arrowSide) {
      let sliderBoxEl = document.querySelector('.slider__box')
      //let widthSliderBox = +this.sliderImages.length-1 + '00'
      let valueLeft = +/\d+/.exec(sliderBoxEl.style.left)
      let gallerySliderEl = document.querySelector('.gallery__slider')
      let valueRight = +/\d+/.exec(window.getComputedStyle(gallerySliderEl).right)
      let arrowLeft = document.querySelector('.left')
             
      if ($arrowSide == 'left' ) {
       
        if (valueRight != 0) {
          
          this.checkShowSlider = true
          arrowLeft.classList.add('hide')
          return this.$emit("clickSlider", this.checkShowSlider)
         
        } //else if (valueLeft != widthSliderBox) {
          
          //sliderBoxEl.style.left = -valueLeft - 100 + '%'
        //}
      } else if ($arrowSide == 'right') {
       
        if (valueRight == 0 && valueLeft == 0 ) {
          
          this.checkShowSlider = false
          arrowLeft.classList.remove('hide')
          return this.$emit("clickSlider", this.checkShowSlider)
        
        } //else if ( valueLeft != 0) {
          
          //sliderBoxEl.style.left = -valueLeft + 100 + '%'
        
        //}
      }
    },
  },
}
</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.slider {
  width: 100%;
  height: 100%;

  &.active {
    
    .slider__arrow.left {
      
      .arrow {
        transform: rotate(180deg);
        
      }
    }
  }

  &__wrapper {
    height: 100%;
    overflow: hidden;
  }

  &__box {
    position: relative;
    @include baseRow();
    width: 100%;
    height: 100%;
    left: 0%;
    transition: all 1.5s ease;

    .box {

      &__item {
        width: 100%;
        height: 100%;
        //background-image: url("~@/assets/images/gallery/gallery-gun.png");
        background-repeat: no-repeat;
        background-position: 50% 50%;
        background-size: cover;
        border-radius: 5px;
      }
    }
  }
    
  &__arrow {
    @include baseRow();
    width: 67px;
    height: 664px;
    background-color: grayColor(500);
    border-radius: 5px;
    cursor: pointer;

    &:hover {
      background-color: grayColor(400);
    }
    
    &:active {
      opacity: 0.8;
    }

    &.left {
      position: absolute;
      top: 0;
      left: -88px;
      transform: scale(-1, 1);
    }

    &.right {
      position: absolute;
      top: 0;
      right: -88px;
      transform: scale(-1, 1);
    }

    &.hide {
      display: none;
    }

    .arrow {
      position: relative;
      height: 50px;
      transition: all 2s ease;
      
      .arrow__part-up {
        position: relative;
        top: 1.5px;
        width: 2.5px;
        height: 28.68px;
        background: $mainTextColor;
        transform: matrix(-0.71, -1.16, 0.43, -0.71, 0, 0);
      }

      .arrow__part-down {
        position: relative;
        bottom: 9.5px;
        width: 2.5px;
        height: 28.68px;
        background: $mainTextColor;
        transform: matrix(-0.71, 1.16, -0.43, -0.71, 0, 0);
      }
    }
  }
}

@media (max-width:1400px){
  .slider {
 

    &__box {
    
      .box {

        &__item {
        
        }
      }
    }
    
    &__arrow {
      opacity: 0.1;
      
      &:hover {
        //background-color: grayColor(400);
        opacity: 0.2;
      }
      
      &:active {
        opacity: 0.1;
      }

      &.left {
        left: 0px;
        
      }

      &.right {
        right: 0px;
        
      }
    }
  }
}
@media (max-width: 1200px){
  .slider {
    
    &__arrow {
      height: 550px;
    }
  }
}
@media (max-width: 992px){
  .slider {
 

    &__box {
    
      .box {

        &__item {
        
        }
      }
    }
    
    &__arrow {
      height: 450px;
      
      &:hover {
        
      }
      
      &:active {
        
      }

      &.left {
        
        
      }

      &.right {
        
        
      }
    }
  }
}
</style>