<template lang="pug">
  .popup
    .popup__center
      .overflow
      p.popup__header Purchase
      p.popup__text Click the following links to buy the rifle online
      popup-link(
        v-for="link of purchaseLinks"
        :key="link.id"
        :link="link"
        :hoverLinkName.sync="hoverLinkName"
      )
      .close(
        @click="onClick"
      )
</template>

<script>
import PopupLink from '@/components/PopupLink';

export default {
  name: "purchase-window",
  components: {
    PopupLink,
  },
  props: {
   
  },
  data: () => ({
    hoverLink: null,
    purchaseLinks: [
      {id: 1, name:'virtualnyeochki.ru', href: 'https://virtualnyeochki.ru/aksessuary/kontroller-avtomat-zeus-3-000'},
      {id: 2, name:'look-journal.ru', href: 'https://look-journal.ru/catalog/view/zeus-3000'},
      {id: 3, name:'gadgilla.com', href: 'https://www.gadgilla.com/collection/kontrollery-vr/product/avtomat-virtualnoy-realnosti-zeus-3-000'}
    ],
    hoverLinkName: ''
  }),
  methods: {
    onClick: function () {
      this.$emit("onClick")
      //console.log("click")
    },
  },
}
</script>

<style lang="scss">
@import "~@/scss/fonts.scss";
@import "~@/scss/variables.scss";
@import "~@/scss/mixins.scss";

.popup {
  position: fixed;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  z-index: 3;
  background: rgba(28, 28, 28, 0.9);
  backdrop-filter: blur(2px);
  display: flex;
  justify-content: center;
  align-items: center;
  color: #000;

  .overflow {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: 60px;
    background-color: #F4F4F4;
    z-index: 5;
  }

  &__header {
    @include baseText(Bold, 36px, grayColor(900));
    text-shadow: 0px 4px 20px rgba(0, 0, 0, 0.3);
    text-transform: uppercase;
    text-align: left;
  }

  &__text {
    font-size: 24px;
    text-align: left;
    margin-top: 25px;
  }

  &__center {
    width: 841px;
    height: 456px;
    background: $backgroundPurchaseWindow;
    position: relative;
    border-radius: 5px;
    padding: 48px 60px;
    box-sizing: border-box;
    overflow: hidden;
  }

  .close {
    position: absolute;
    right: 32px;
    top: 32px;
    width: 32px;
    height: 32px;
    opacity: 0.3;

    &:hover {
      opacity: 1;
    }
    &::before, &::after {
      position: absolute;
      left: 15px;
      content: ' ';
      height: 33px;
      width: 2px;
      background-color: grayColor(900);
    }
    &::before {
      transform: rotate(45deg);
    }
    &::after {
      transform: rotate(-45deg);
    }
  }
}

@media (max-width:425px) {
  .popup {
  
    .overflow {
      display: none;
    }

    &__header {
      font-size: 18px;
      text-align: center;
    }

    &__text {
      font-size: 10px;
      text-align: center;
      margin-top: 20px;
    }

    &__center {
      padding: 30px 25px;
      margin: 10px;
      height: 320px;
    }

    .close {
      right: 10px;
      top: 10px;

      &::before, &::after {
        height: 25px;
      }
    }
  }
}

</style>
